import{_ as t,o as d,c as a,Q as r}from"./chunks/framework.48927342.js";const u=JSON.parse('{"title":"婚礼邀请邮件","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/practice/emails/03-wedding-invitation.md","filePath":"zh/more/maltese/practice/emails/03-wedding-invitation.md"}'),e={name:"zh/more/maltese/practice/emails/03-wedding-invitation.md"},o=r('<h1 id="婚礼邀请邮件" tabindex="-1">婚礼邀请邮件 <a class="header-anchor" href="#婚礼邀请邮件" aria-label="Permalink to &quot;婚礼邀请邮件&quot;">​</a></h1><p><strong>场景：</strong> 一对新人邀请亲友参加婚礼仪式和宴会。</p><h2 id="邮件头部" tabindex="-1">邮件头部 <a class="header-anchor" href="#邮件头部" aria-label="Permalink to &quot;邮件头部&quot;">​</a></h2><p><strong>Lil（收件人 To）：</strong> <a href="mailto:hbieb@gmail.com" target="_blank" rel="noreferrer">hbieb@gmail.com</a><strong>Mingħand（发件人 From）：</strong> <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a><strong>Data（日期）：</strong> 20 ta&#39; Ġunju 2026 <strong>Suġġett（主题）：</strong> Stedina għat-tieġ</p><h2 id="邮件全文" tabindex="-1">邮件全文 <a class="header-anchor" href="#邮件全文" aria-label="Permalink to &quot;邮件全文&quot;">​</a></h2><blockquote><p><strong>Lil:</strong> <a href="mailto:hbieb@gmail.com" target="_blank" rel="noreferrer">hbieb@gmail.com</a><strong>Mingħand:</strong> <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a><strong>Data:</strong> 20 ta&#39; Ġunju 2026 <strong>Suġġett:</strong> Stedina għat-tieġ</p><p>Għeżież ħbieb,</p><p>Għandna pjaċir nistednukom għat-tieġ tagħna.</p><p>Iċ-ċerimonja se ssir nhar is-Sibt, 18 ta&#39; Lulju.</p><p>Tibda fil-ħamsa ta&#39; wara nofsinhar fil-knisja ta&#39; San Pawl.</p><p>Wara ċ-ċerimonja, se jkun hemm riċeviment fil-lukanda Marina.</p><p>Jekk jogħġobkom, ikkonfermaw jekk tistgħux tattendu sal-1 ta&#39; Lulju.</p><p>Nistennew bil-ħerqa li niċċelebraw dan il-jum speċjali magħkom.</p><p>Tislijiet, Anna u Mark</p></blockquote><h2 id="逐句翻译与逐词拆解" tabindex="-1">逐句翻译与逐词拆解 <a class="header-anchor" href="#逐句翻译与逐词拆解" aria-label="Permalink to &quot;逐句翻译与逐词拆解&quot;">​</a></h2><p><strong>Malti:</strong> Lil: <a href="mailto:hbieb@gmail.com" target="_blank" rel="noreferrer">hbieb@gmail.com</a></p><p><strong>整句：</strong> 收件人（To）：hbieb@gmail.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Lil</td><td>收件人；给……</td><td>邮件头部&quot;To&quot;的马耳他语标签</td></tr><tr><td><a href="mailto:hbieb@gmail.com" target="_blank" rel="noreferrer">hbieb@gmail.com</a></td><td>邮箱地址</td><td>收件人（受邀亲友们）的邮箱</td></tr></tbody></table><p><strong>Malti:</strong> Mingħand: <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></p><p><strong>整句：</strong> 发件人（From）：anna.c@gmail.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Mingħand</td><td>发件人；来自……</td><td>邮件头部&quot;From&quot;的马耳他语标签，本义&quot;从……那里&quot;</td></tr><tr><td><a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></td><td>邮箱地址</td><td>发件人（Anna）的邮箱</td></tr></tbody></table><p><strong>Malti:</strong> Data: 20 ta&#39; Ġunju 2026</p><p><strong>整句：</strong> 日期：2026 年 6 月 20 日</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Data</td><td>日期</td><td>邮件头部&quot;Date&quot;；马耳他语日期格式为&quot;日 ta&#39; 月 年&quot;</td></tr><tr><td>20</td><td>二十</td><td>日期中的日</td></tr><tr><td>ta&#39;</td><td>……的</td><td>连接日和月份</td></tr><tr><td>Ġunju</td><td>六月</td><td>月份名</td></tr></tbody></table><p><strong>Malti:</strong> Suġġett: Stedina għat-tieġ</p><p><strong>整句：</strong> 主题：婚礼邀请</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Suġġett</td><td>主题</td><td>邮件头部&quot;Subject&quot;</td></tr><tr><td>Stedina</td><td>邀请</td><td>阴性名词</td></tr><tr><td>għat-tieġ</td><td>参加婚礼</td><td><code>għal</code> + <code>it-tieġ</code> 的缩合形式</td></tr></tbody></table><p><strong>Malti:</strong> Għeżież ħbieb,</p><p><strong>整句：</strong> 亲爱的朋友们：</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għeżież</td><td>亲爱的</td><td>阳性复数形式，用于称呼一群人</td></tr><tr><td>ħbieb</td><td>朋友们</td><td><code>ħabib</code> 的复数</td></tr></tbody></table><h3 id="_1" tabindex="-1">1. <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;1.&quot;">​</a></h3><p><strong>Malti:</strong> Għandna pjaċir nistednukom għat-tieġ tagħna.</p><p><strong>整句：</strong> 我们很高兴邀请你们参加我们的婚礼。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għandna</td><td>我们有</td><td><code>għand</code> 的第一人称复数形式</td></tr><tr><td>pjaċir</td><td>愉快；荣幸</td><td><code>għandna pjaċir</code> 整体表示“我们很高兴/荣幸”</td></tr><tr><td>nistednukom</td><td>我们邀请你们</td><td><code>nistiednu</code>“我们邀请” + <code>-kom</code>“你们”</td></tr><tr><td>għat-tieġ</td><td>去婚礼；参加婚礼</td><td><code>għal</code> + <code>it-tieġ</code> 的缩合形式</td></tr><tr><td>tagħna</td><td>我们的</td><td>第一人称复数所有格</td></tr></tbody></table><h3 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h3><p><strong>Malti:</strong> Iċ-ċerimonja se ssir nhar is-Sibt, 18 ta&#39; Lulju.</p><p><strong>整句：</strong> 婚礼仪式将于 7 月 18 日星期六举行。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Iċ-ċerimonja</td><td>仪式</td><td>阴性名词，带定冠词</td></tr><tr><td>se</td><td>将；会</td><td>将来标记</td></tr><tr><td>ssir</td><td>举行；发生</td><td><code>isir</code> 的阴性形式，与 <code>ċerimonja</code> 一致</td></tr><tr><td>nhar</td><td>在……那天</td><td>引出星期或日期</td></tr><tr><td>is-Sibt</td><td>星期六</td><td>星期名称带定冠词</td></tr><tr><td>18</td><td>十八</td><td>日期中的日</td></tr><tr><td>ta&#39;</td><td>……的</td><td>日期结构中连接日和月份</td></tr><tr><td>Lulju</td><td>七月</td><td>月份名</td></tr></tbody></table><h3 id="_3" tabindex="-1">3. <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;3.&quot;">​</a></h3><p><strong>Malti:</strong> Tibda fil-ħamsa ta&#39; wara nofsinhar fil-knisja ta&#39; San Pawl.</p><p><strong>整句：</strong> 仪式下午五点在圣保罗教堂开始。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Tibda</td><td>它开始</td><td>第三人称阴性单数，指仪式</td></tr><tr><td>fil-ħamsa</td><td>在五点</td><td><code>f&#39;</code>“在” + 钟点形式缩合</td></tr><tr><td>ta&#39;</td><td>……的；在……时段</td><td>连接时间和时段</td></tr><tr><td>wara</td><td>之后</td><td>与 <code>nofsinhar</code> 合成“下午”</td></tr><tr><td>nofsinhar</td><td>中午</td><td><code>wara nofsinhar</code> 表示下午</td></tr><tr><td>fil-knisja</td><td>在教堂</td><td><code>f&#39;</code> + <code>il-knisja</code> 的缩合形式</td></tr><tr><td>ta&#39;</td><td>……的</td><td>连接地点名称</td></tr><tr><td>San</td><td>圣</td><td>人名前的称谓</td></tr><tr><td>Pawl</td><td>保罗</td><td>人名</td></tr></tbody></table><h3 id="_4" tabindex="-1">4. <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;4.&quot;">​</a></h3><p><strong>Malti:</strong> Wara ċ-ċerimonja, se jkun hemm riċeviment fil-lukanda Marina.</p><p><strong>整句：</strong> 仪式之后，我们将在 Marina 酒店举行宴会。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Wara</td><td>在……之后</td><td>时间介词</td></tr><tr><td>ċ-ċerimonja</td><td>仪式</td><td><code>iċ-ċerimonja</code> 在此处省去句首元音写法，指婚礼仪式</td></tr><tr><td>se</td><td>将；会</td><td>将来标记</td></tr><tr><td>jkun</td><td>会是；会有</td><td><code>ikun</code> 的形式</td></tr><tr><td>hemm</td><td>有；那里</td><td><code>se jkun hemm</code> 表示“将会有”</td></tr><tr><td>riċeviment</td><td>招待会；宴会</td><td>阳性名词，借词</td></tr><tr><td>fil-lukanda</td><td>在酒店</td><td><code>f&#39;</code> + <code>il-lukanda</code> 的缩合形式</td></tr><tr><td>Marina</td><td>Marina</td><td>酒店名称</td></tr></tbody></table><h3 id="_5" tabindex="-1">5. <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;5.&quot;">​</a></h3><p><strong>Malti:</strong> Jekk jogħġobkom, ikkonfermaw jekk tistgħux tattendu sal-1 ta&#39; Lulju.</p><p><strong>整句：</strong> 麻烦你们在 7 月 1 日前确认是否能够出席。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Jekk jogħġobkom</td><td>请；麻烦你们</td><td>对多人使用的礼貌表达</td></tr><tr><td>ikkonfermaw</td><td>请确认</td><td>对多人的命令式</td></tr><tr><td>jekk</td><td>是否；如果</td><td>此处引出间接疑问</td></tr><tr><td>tistgħux</td><td>你们能否</td><td><code>tistgħu</code>“你们能够” + 否定/疑问标记 <code>-x</code></td></tr><tr><td>tattendu</td><td>你们出席</td><td>第二人称复数形式</td></tr><tr><td>sal-1</td><td>到……为止；截至 1 日</td><td><code>sa</code> + <code>l-</code> 的缩合形式</td></tr><tr><td>ta&#39;</td><td>……的</td><td>日期结构连接词</td></tr><tr><td>Lulju</td><td>七月</td><td>月份名</td></tr></tbody></table><h3 id="_6" tabindex="-1">6. <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;6.&quot;">​</a></h3><p><strong>Malti:</strong> Nistennew bil-ħerqa li niċċelebraw dan il-jum speċjali magħkom.</p><p><strong>整句：</strong> 我们期待和你们一起庆祝这个特别的日子。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nistennew</td><td>我们等待；我们期待</td><td>第一人称复数形式</td></tr><tr><td>bil-ħerqa</td><td>热切地；期待地</td><td>固定副词短语</td></tr><tr><td>li</td><td>……；引出从句</td><td>连词</td></tr><tr><td>niċċelebraw</td><td>我们庆祝</td><td>第一人称复数形式</td></tr><tr><td>dan</td><td>这个</td><td>阳性单数指示词，与 <code>jum</code> 一致</td></tr><tr><td>il-jum</td><td>日子</td><td>阳性名词，带定冠词</td></tr><tr><td>speċjali</td><td>特别的</td><td>形容词</td></tr><tr><td>magħkom</td><td>和你们一起</td><td><code>ma&#39;</code>“和” + <code>-kom</code>“你们”</td></tr></tbody></table><p><strong>Malti:</strong> Tislijiet, Anna u Mark</p><p><strong>整句：</strong> 此致敬意，安娜和马克（邮件落款）。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Tislijiet</td><td>此致敬意；致以问候</td><td>正式邮件/信件落款用语，本义&quot;问候/致意&quot;</td></tr><tr><td>Anna</td><td>安娜</td><td>人名</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>Mark</td><td>马克</td><td>人名</td></tr></tbody></table>',49),n=[o];function i(l,h,s,c,g,b){return d(),a("div",null,n)}const p=t(e,[["render",i]]);export{u as __pageData,p as default};
